package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
)

var vis [110][110]int
var directions = [4][2]int{
	{0, 1},
	{1, 0},
	{0, -1},
	{-1, 0},
}

type Node struct {
	x, y, step int
}

type PriorityQueue []Node

func (pq PriorityQueue) Len() int {
	return len(pq)
}

func (pq PriorityQueue) Less(i, j int) bool {
	return pq[i].step < pq[j].step
}

func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
}

func (pq *PriorityQueue) Push(x interface{}) {
	*pq = append(*pq, x.(Node))
}

func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[:n-1]
	return item
}

func bfs(l, u, xi, yi int) int {
	pq := &PriorityQueue{}
	heap.Init(pq)
	heap.Push(pq, Node{l, u, 0})
	vis[l][u] = 1

	for pq.Len() > 0 {
		e := heap.Pop(pq).(Node)
		if e.x == xi && e.y == yi {
			return e.step
		}

		for i := 0; i < 4; i++ {
			t := Node{
				x:    e.x + directions[i][0],
				y:    e.y + directions[i][1],
				step: e.step + 1,
			}

			if t.x < 0 || t.y < 0 {
				continue
			}
			if vis[t.x][t.y] != 0 {
				continue
			}

			vis[t.x][t.y] = 1
			heap.Push(pq, t)
		}
	}

	return 0
}

